"""Render the evidence-based journey as a portable, dependency-free HTML page."""
from pathlib import Path
import html
import markdown
from bs4 import BeautifulSoup

ROOT=Path(__file__).resolve().parents[1]
REPO='https://github.com/az9713/gpt-6-astra-tennis-game'
source=(ROOT/'DEVELOPMENT-JOURNEY.md').read_text(encoding='utf-8')
soup=BeautifulSoup(markdown.markdown(source,extensions=['tables','fenced_code','toc','sane_lists']), 'html.parser')
soup.h1.decompose()
nav=''.join(f'<a href="#{h["id"]}">{html.escape(h.get_text())}</a>' for h in soup.select('h2'))
for p in soup.select('p'):
    if p.strong and p.get_text().startswith('“'):
        title=p.strong.extract().get_text()
        detail=soup.new_tag('details'); summary=soup.new_tag('summary'); summary.string=title
        detail.append(summary); p.replace_with(detail); detail.append(p)
for table in soup.select('table'):
    wrapper=soup.new_tag('div',attrs={'class':'table-scroll','tabindex':'0','role':'region','aria-label':'Scrollable comparison table'})
    table.wrap(wrapper)
for img in soup.select('img'):
    img['loading']='lazy'; img['decoding']='async'
for a in soup.select('a[href]'):
    href=a['href']
    if not href.startswith(('http','#','mailto:')) and not href.startswith('docs/'):
        a['href']=REPO+'/blob/main/'+href

arc='''<aside class="experiment" aria-labelledby="arc-title"><span class="eyebrow">TRY THE DESIGN DECISION</span><h3 id="arc-title">More flight time. A higher arc.</h3><p>The illustration fixes a 20 m horizontal journey, a 1 m release height and gravity at 9.81 m/s². It solves the launch velocity needed to reach the ground at the chosen time. The game applies the same principle with its own court targets and clearance checks.</p><label for="flight">Flight time: <output id="flight-value">1.55 s</output></label><input id="flight" type="range" min="1.18" max="2" step="0.01" value="1.55"><svg viewBox="0 0 720 260" role="img" aria-label="Ball trajectory for selected flight time"><path d="M30 225H690 M360 225V199" fill="none" stroke="#638e88" stroke-width="2"/><text x="365" y="192">net illustration</text><path id="arc" fill="none" stroke="#e7835d" stroke-width="5"/><circle id="ball" r="8" fill="#d7ed79"/><text x="30" y="250">release</text><text x="620" y="250">20 metres</text></svg><p id="arc-stats" aria-live="polite"></p><noscript>The diagram requires JavaScript. The explanation and equations above remain readable.</noscript></aside>'''
for p in soup.select('p'):
    if 'HTML version includes an interactive illustration' in p.get_text():
        p.insert_after(BeautifulSoup(arc,'html.parser'))

css='''
:root{--paper:#f4f0e7;--ink:#163932;--muted:#5e7268;--line:#ced6c8;--clay:#bb573b;--mint:#d6e7b7}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:35px}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.75 system-ui,-apple-system,Segoe UI,sans-serif}a{color:#246d61;text-underline-offset:4px}a:hover{color:var(--clay)}.skip{position:absolute;left:20px;top:-80px;background:white;padding:12px;z-index:9}.skip:focus{top:10px}#progress{position:fixed;top:0;left:0;height:4px;background:#d7855c;z-index:10;width:0}.mast{display:flex;justify-content:space-between;gap:20px;padding:22px 5vw;background:var(--ink);color:#e8edda;font-size:12px;letter-spacing:.13em;text-transform:uppercase}.mast a{color:#e8edda}.hero{background:var(--ink);color:var(--paper);padding:56px 5vw 68px;display:grid;grid-template-columns:1fr 1.08fr;gap:5vw;align-items:center}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.17em;text-transform:uppercase;color:#8bba9d}.hero h1{font-family:Georgia,serif;font-size:clamp(48px,5.7vw,90px);line-height:1.02;letter-spacing:-.045em;font-weight:400;margin:24px 0}.hero h1 em{color:#e79670}.hero p{max-width:580px;color:#d3dfce;font-size:19px}.hero img{width:100%;border-radius:4px;display:block}.caption{font-size:12px;opacity:.75;margin-top:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line);padding:25px 5vw;gap:20px}.stats b{display:block;font:34px Georgia,serif}.stats span{font-size:12px;color:var(--muted)}.layout{display:grid;grid-template-columns:240px minmax(0,900px);gap:5vw;max-width:1400px;margin:auto;padding:65px 4vw}.side{position:sticky;top:28px;align-self:start;font-size:12px;max-height:92vh;overflow:auto}.side strong{letter-spacing:.13em}.side nav{margin:20px 0}.side a{display:block;text-decoration:none;border-left:2px solid var(--line);padding:9px 0 9px 14px;line-height:1.5}.side a.active{border-color:var(--clay);color:var(--clay);font-weight:bold}button{font:inherit;color:var(--ink);border:1px solid #9aae9b;background:transparent;border-radius:4px;padding:7px 11px;cursor:pointer}.side button{margin:6px 0;width:100%;text-align:left}main{min-width:0}main>p:first-child{font:28px/1.45 Georgia,serif}h2{font:42px/1.2 Georgia,serif;letter-spacing:-.025em;padding-top:58px;margin-top:68px;border-top:1px solid var(--line)}h3{font:27px/1.35 Georgia,serif;margin-top:36px}p{margin:18px 0}li{margin:8px 0}blockquote{margin:26px 0;padding:12px 28px;border-left:3px solid var(--clay);background:#eae8dc;font-size:16px}code{font:13px/1.5 Consolas,monospace;background:#e8e9df;padding:2px 5px;overflow-wrap:anywhere}pre{background:#183b33;color:#f2f0df;padding:22px;overflow:auto;border-radius:5px}pre code{background:none;padding:0;color:inherit;white-space:pre;font-size:13px}.table-scroll{overflow-x:auto;margin:28px 0}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.6}th{text-align:left;background:#dce3d4}td,th{padding:13px 15px;border-bottom:1px solid var(--line);vertical-align:top}tr:nth-child(even){background:#eceee3}main img{display:block;width:auto;max-width:100%;max-height:650px;margin:28px auto;border-radius:5px}main img[src*="robot-reference"],main img[src*="meshy-preview"]{max-width:min(100%,420px)}details{border-bottom:1px solid var(--line);padding:18px 0}summary{font-weight:650;cursor:pointer;line-height:1.6}details p{color:#42594c;padding-left:20px}.experiment{margin:35px 0;background:var(--ink);color:var(--paper);padding:30px;border-radius:6px}.experiment h3{margin-top:10px}.experiment p{font-size:14px;color:#d1deca}.experiment input{display:block;width:100%;margin:20px 0;accent-color:#e79670}.experiment svg{display:block;width:100%;height:auto}.experiment svg text{fill:#c6dac5;font:12px system-ui}video{width:100%;border-radius:6px;background:var(--ink)}.film{margin:35px 0 60px}.pipeline{display:flex;flex-wrap:wrap;gap:8px;margin:25px 0}.pipeline span{color:var(--ink);background:#dce6cb;border:1px solid #b5c9a7;border-radius:4px;padding:8px 13px;font-size:13px}footer{padding:40px 5vw;background:var(--ink);color:#d3dfce;font-size:13px}footer a{color:#c7dfa2}:focus-visible{outline:3px solid #cd7c4f;outline-offset:4px}@media(max-width:1000px){.layout{grid-template-columns:190px minmax(0,1fr);gap:30px}.hero{grid-template-columns:1fr}.hero img{max-width:800px}.hero h1{max-width:750px}.hero p{max-width:800px}}@media(max-width:700px){body{font-size:16px}.mast{font-size:10px}.hero{padding:35px 6vw}.hero h1{font-size:54px}.stats{grid-template-columns:repeat(2,1fr)}.layout{display:block;padding:35px 6vw}.side{position:static;max-height:none;margin-bottom:38px}.side nav{display:grid;grid-template-columns:1fr 1fr;gap:5px}.side button{width:auto;margin-right:10px}h2{font-size:33px;margin-top:45px;padding-top:35px}h3{font-size:25px}.experiment{padding:20px}td,th{padding:10px;min-width:130px}blockquote{padding:8px 20px}.hero p{font-size:17px}}@media print{.side,.mast,#progress,button,input,video{display:none}.hero{display:block;background:white;color:black;padding:0}.hero p{color:black}.hero img{max-width:500px}.hero h1{font-size:42px}.stats{padding:10px 0}.layout{display:block;padding:0}body{font-size:11pt;background:white;color:black}h2{font-size:25pt;margin-top:25px;padding-top:20px;break-after:avoid}h3{break-after:avoid}pre,.experiment{color:black;background:#eee}.experiment p{color:black}.table-scroll{overflow:visible}a{color:inherit}footer{background:white;color:black}}
'''
js='''
const slider=document.getElementById('flight');
function draw(){const t=+slider.value,g=9.81,y0=1,d=20,vy=(.5*g*t*t-y0)/t;let path='';for(let i=0;i<=100;i++){let s=t*i/100,x=30+660*i/100,y=225-30*(y0+vy*s-.5*g*s*s);path+=(i?'L':'M')+x.toFixed(2)+' '+y.toFixed(2)+' ';}document.getElementById('arc').setAttribute('d',path);let s=t*.42;document.getElementById('ball').setAttribute('cx',30+660*.42);document.getElementById('ball').setAttribute('cy',225-30*(y0+vy*s-.5*g*s*s));document.getElementById('flight-value').textContent=t.toFixed(2)+' s';document.getElementById('arc-stats').textContent='Horizontal speed: '+(d/t).toFixed(1)+' m/s · Upward launch speed: '+vy.toFixed(1)+' m/s · Peak height: '+(y0+vy*vy/(2*g)).toFixed(2)+' m';}slider.addEventListener('input',draw);draw();
document.getElementById('expand').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=true);document.getElementById('collapse').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=false);document.getElementById('print').onclick=()=>{document.querySelectorAll('details').forEach(d=>d.open=true);window.print()};
const links=[...document.querySelectorAll('.side nav a')];function progress(){const total=document.documentElement.scrollHeight-innerHeight;document.getElementById('progress').style.width=(total?100*scrollY/total:0)+'%';let current=links[0];for(const a of links){if(document.querySelector(a.getAttribute('href')).getBoundingClientRect().top<150)current=a;}links.forEach(a=>a.classList.toggle('active',a===current));}addEventListener('scroll',progress,{passive:true});progress();
'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="An evidence-based development journey from a YouTube reference to an AI-built Unity tennis prototype: Blender, Meshy, failures, human decisions and verification."><title>Robo Open — The Development Journey</title><style>{css}</style></head><body><a class="skip" href="#journey">Skip to the journey</a><div id="progress"></div><header class="mast"><span>Robo Open / Development field notes</span><a href="{REPO}">Source &amp; Windows download</a></header><section class="hero"><div><span class="eyebrow">A largely autonomous build · 05 September 2026</span><h1>From a video.<br>To a <em>playable court.</em></h1><p>The entire development journey: what the human decided, what the agent built, what broke, and how each claim was checked.</p><div class="pipeline"><span>Reference →</span><span>Image →</span><span>Meshy →</span><span>Blender →</span><span>Unity →</span><span>Windows</span></div></div><div><img src="docs/media/prototype-rally.png" alt="Two toy robots rally on the coral court in the actual Windows prototype"><div class="caption">Actual rendered prototype. Newly created assets; inspired by Chong-U’s video.</div></div></section><section class="stats" aria-label="Recorded project facts"><div><b>30</b><span>Meshy credits consumed</span></div><div><b>16 / 5</b><span>Robot bones / animation clips</span></div><div><b>17 + 17</b><span>Rules and input checks passed</span></div><div><b>9</b><span>Human messages through prototype delivery</span></div></section><div class="layout"><aside class="side"><strong>THE JOURNEY</strong><nav>{nav}</nav><button id="expand">Expand every question</button><button id="collapse">Collapse questions</button><button id="print">Print / save as PDF</button><a href="{REPO}/blob/main/DEVELOPMENT-JOURNEY.md">Read the Markdown source</a></aside><main id="journey"><section class="film" aria-label="Match recording"><span class="eyebrow" style="color:#537752">WATCH THE RESULT</span><h3>A short match, in motion</h3><video controls preload="metadata" playsinline poster="docs/media/prototype-serve.png"><source src="docs/media/match.mp4" type="video/mp4"><a href="docs/media/match.mp4">Download the match recording</a></video><p class="caption">56.5 seconds · silent H.264 · 2.81 MB · 94% smaller than the supplied recording.</p></section>{soup}</main></div><footer>Robo Open · Evidence, decisions and limitations preserved.<br><a href="https://www.youtube.com/watch?v=DQfL_l5lRpk">Original YouTube inspiration</a> · <a href="{REPO}">Repository</a></footer><script>{js}</script></body></html>'''
(ROOT/'DEVELOPMENT-JOURNEY.html').write_text(page,encoding='utf-8')
(ROOT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta http-equiv="refresh" content="0; url=DEVELOPMENT-JOURNEY.html"><title>Robo Open</title><a href="DEVELOPMENT-JOURNEY.html">Read the Robo Open development journey</a></html>',encoding='utf-8')
(ROOT/'.nojekyll').touch()
print('Rendered DEVELOPMENT-JOURNEY.html')
